<template><section class="stock-forecast" aria-label="Twelve-month stock-price scenarios"><header><div><p>{{ forecast.provisional?'Provisional 12-month share-price scenarios':'12-month share-price scenarios' }}</p><h3 v-if="forecast.available">{{ pct(forecast.cases[0].return) }} to {{ pct(forecast.cases[2].return) }}</h3><h3 v-else>Price range unavailable</h3></div><aside v-if="forecast.available"><strong>{{ money(forecast.cases[0].price,forecast.currency) }} – {{ money(forecast.cases[2].price,forecast.currency) }}</strong><span>Target date {{ forecast.target||'Not recorded' }} · {{ forecast.currency }}</span></aside></header><template v-if="forecast.available"><p v-if="forecast.provisional" class="forecast-source">Conditional numerical scenarios remain provisional while the overall evidence is insufficient. These are not a new investment recommendation.</p><div class="forecast-cases"><article v-for="scenario in forecast.cases" :key="scenario.key"><p>{{ scenario.label }}</p><strong>{{ money(scenario.price,forecast.currency) }}</strong><b>{{ pct(scenario.return) }} share-price return</b><details><summary>Agent assumptions</summary><p>{{ scenario.reason||'Reason not recorded' }}</p></details></article></div><p class="forecast-source">Reference {{ money(forecast.reference,forecast.currency) }} · as of {{ forecast.asOf?date(forecast.asOf):'Not recorded' }} · {{ forecast.evidence }} evidence. Scenario estimates, not a confidence interval or validated prediction.</p><div class="forecast-reasons"><article><h4>Supporting analyst</h4><p><StockEvidenceText :text="excerpt(forecast.support)" :sources="run.dossier?.sources||[]"/></p></article><article><h4>Opposing analyst</h4><p><StockEvidenceText :text="excerpt(forecast.oppose)" :sources="run.dossier?.sources||[]"/></p></article></div></template><p v-else class="forecast-source">{{ forecast.reason }}</p><button @click="$emit('debate')">Read the full one-year debate →</button></section></template>
<script setup>
import {computed} from 'vue'
import StockEvidenceText from './StockEvidenceText.vue'
import {stockForecast} from '../utils/stockForecast.mjs'
import {money,date} from '../api/stocklab'
const props=defineProps({run:Object})
defineEmits(['debate'])
const forecast=computed(()=>stockForecast(props.run))
const pct=value=>Number.isFinite(value)?`${value>=0?'+':''}${(value*100).toFixed(1)}%`:'Unavailable'
const excerpt=text=>text?text.length>220?text.slice(0,217).replace(/\s+\S*$/,'')+'…':text:'No saved argument is available.'
</script>
<style scoped>
.stock-forecast{border:1px solid #dfe6ee;border-radius:7px;background:white;padding:19px;margin:15px 0;color:#283849}.stock-forecast>header{display:flex;align-items:center;justify-content:space-between;gap:20px}.stock-forecast header p{font-size:12px;color:#66788e;margin:0 0 6px}.stock-forecast h3{font-size:29px;font-weight:550;letter-spacing:-.7px;margin:0}.stock-forecast aside{display:grid;gap:6px;text-align:right}.stock-forecast aside strong{font-size:20px;font-weight:500}.stock-forecast aside span{font-size:11px;color:#758294}.forecast-cases{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:18px 0}.forecast-cases article{border:1px solid #e5ebf2;border-radius:5px;padding:12px}.forecast-cases p{font-size:11px;color:#65788d;margin:0 0 6px}.forecast-cases strong{font-size:22px;font-weight:550;display:block;font-variant-numeric:tabular-nums}.forecast-cases b{font-size:11px;font-weight:400;display:block;color:#8b684d;margin-top:5px}.forecast-cases summary{font-size:10px;color:#a73508;cursor:pointer;margin-top:10px}.forecast-cases details p{margin-top:10px;line-height:1.6}.forecast-source{font-size:11px;color:#768397;line-height:1.7}.forecast-reasons{display:grid;grid-template-columns:1fr 1fr;gap:20px;border-top:1px solid #e5ebf2;padding-top:13px;margin-top:14px}.forecast-reasons h4{font-size:12px;font-weight:500;margin:0 0 6px}.forecast-reasons p{font-size:12px;color:#62748c;line-height:1.65;margin:0}.stock-forecast>button{font-size:12px;border:0;background:none;color:#a73508;padding:14px 0 0;cursor:pointer}@media(max-width:620px){.stock-forecast{padding:14px}.stock-forecast>header{align-items:start;flex-direction:column;gap:12px}.stock-forecast aside{text-align:left}.stock-forecast h3{font-size:25px}.forecast-cases{gap:6px}.forecast-cases article{padding:9px}.forecast-cases strong{font-size:17px}.forecast-reasons{grid-template-columns:1fr;gap:13px}}
</style>
